-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT     TRUNC(SYSDATE)                                  AS \"Report Date\",     im.DEPT                                         AS \"Dept No\",     d.DEPT_NAME                                     AS \"Dept Name\",     im.CLASS                                        AS \"Class No\",     c.CLASS_NAME                                    AS \"Class Name\",     im.SUBCLASS                                     AS \"Subclass No\",     sc.SUB_NAME                                     AS \"Subclass Name\",     im.ITEM                                         AS \"Item ID\",     im.ITEM_DESC                                    AS \"Item Description\",     im.STANDARD_UOM                                 AS \"UOM\",     im.PACK_IND                                     AS \"Pack IND\",     im.STATUS                                       AS \"Item Status\",     ril.LOCATION                                    AS \"Location ID\",     il.LOC_TYPE                                     AS \"LOC Type\",     CASE il.LOC_TYPE             WHEN 'S'                 THEN 'Store'             WHEN 'W'                 THEN 'Warehouse'     END                                                 AS \"LOC Type DESC\",      CASE il.LOC_TYPE             WHEN 'S'                 THEN st.STORE_NAME             WHEN 'W'                 THEN wh.WH_NAME     END                                                 AS location_name,      il.STATUS                                       AS \"Item LOC Status\",     CASE il.STATUS             WHEN 'A'                 THEN 'Active'             WHEN 'C'                 THEN 'Discontinued'             WHEN 'I'                 THEN 'Inactive'             WHEN 'D'                 THEN 'Delete'     END                                                 AS \"Item LOC Status DESC\",      ril.PRIMARY_REPL_SUPPLIER                       AS \"Supplier ID\",     sp.SUP_NAME                                     AS \"Supplier Name\",     sp.SUP_STATUS                                   AS \"Supplier Status\",     isc.LEAD_TIME                                   AS \"Lead Time\",     isc.PICKUP_LEAD_TIME                            AS \"Pickup Lead Time\",     isc.UNIT_COST                                   AS \"Unit Cost\",     ril.REPL_METHOD                                 AS \"Repl Method\",     CASE ril.REPL_METHOD             WHEN 'C'                 THEN 'Constant'             WHEN 'D'                 THEN 'Dynamic'             WHEN 'F'                 THEN 'Floating Point'             WHEN 'M'                 THEN 'Min/Max'             WHEN 'T'                 THEN 'Time Supply'             WHEN 'SO'                 THEN 'Store Orders'             WHEN 'DI'                 THEN 'Dynamic - Issues'             WHEN 'S'                 THEN 'Dynamic - Seasonal'             WHEN 'TI'                 THEN 'Time Supply - Issues'             WHEN 'E'                 THEN 'Time Supply - Seasonal'             ELSE ril.REPL_METHOD     END                                                 AS \"Repl Method DESC\",      ril.STOCK_CAT                                   AS \"Stock Category\",     CASE ril.STOCK_CAT             WHEN 'C'                 THEN 'Cross-Docked'             WHEN 'D'                 THEN 'Direct to Store'             WHEN 'L'                 THEN 'WH/Cross Link'             WHEN 'W'                 THEN 'Warehouse Stocked'             WHEN 'X'                 THEN 'PO Cross-link'             ELSE ril.STOCK_CAT     END                                                 AS \"Stock Category DESC\",      ril.REPL_ORDER_CTRL                             AS \"Order Control\",     CASE ril.REPL_ORDER_CTRL             WHEN 'A'                 THEN 'Automatic'             WHEN 'B'                 THEN 'Buyer Worksheet'             WHEN 'M'                 THEN 'Manual'             WHEN 'S'                 THEN 'Semi-Automatic'     END                                                 AS \"Order Control DESC\",      ril.MIN_STOCK                                   AS \"Min Stock\",     ril.MAX_STOCK                                   AS \"Max Stock\",     ril.REVIEW_CYCLE                                AS \"Review Cycle\",     ril.SOURCE_WH                                   AS \"Source Warehouse\",     ril.NON_SCALING_IND                             AS \"Scaling Exempt IND\",     last_ord.LAST_ORDER_DATE                        AS \"Last PO Written Date\",     last_ord.LAST_ORDER_NO                          AS \"Last PO Number\",     last_ord.LAST_ORDER_STATUS                      AS \"Last PO Status\",     last_ord.LAST_NOT_AFTER_DATE                    AS \"Last PO Not After Date\",     CASE             WHEN last_ord.LAST_ORDER_DATE IS NULL                 THEN NULL             ELSE TRUNC(SYSDATE) - TRUNC(last_ord.LAST_ORDER_DATE)     END                                                 AS \"Days Since Last Order\",      CASE WHEN last_ord.LAST_ORDER_DATE IS NULL THEN 'NEVER ORDERED'             WHEN TRUNC(SYSDATE) - TRUNC(last_ord.LAST_ORDER_DATE) BETWEEN 30 AND 45                 THEN '30 - 45 Days'             WHEN TRUNC(SYSDATE) - TRUNC(last_ord.LAST_ORDER_DATE) BETWEEN 46 AND 60                 THEN '46 - 60 Days'             WHEN TRUNC(SYSDATE) - TRUNC(last_ord.LAST_ORDER_DATE) BETWEEN 61 AND 90                 THEN '61 - 90 Days'             WHEN TRUNC(SYSDATE) - TRUNC(last_ord.LAST_ORDER_DATE) &gt; 90                 THEN '90+ Days'             ELSE 'WITHIN 30 DAYS'     END                                                 AS \"No Order Aging Bucket\",      ils.STOCK_ON_HAND                               AS \"Current Soh\",     ils.AV_COST                                     AS \"Weighted Avg Cost\",     il.SELLING_UNIT_RETAIL                          AS \"Unit Retail\",     ROUND(NVL(ils.STOCK_ON_HAND, 0) * NVL(ils.AV_COST, 0), 2)AS \"Soh Cost Value\",     CASE WHEN NVL(ils.STOCK_ON_HAND, 0) = 0 THEN 'OUT OF STOCK'             WHEN NVL(ils.STOCK_ON_HAND, 0) &lt; NVL(ril.MIN_STOCK, 0)                 THEN 'BELOW MIN'             WHEN NVL(ils.STOCK_ON_HAND, 0) BETWEEN NVL(ril.MIN_STOCK, 0) AND NVL(ril.MAX_STOCK, 0)                 THEN 'WITHIN RANGE'             WHEN NVL(ils.STOCK_ON_HAND, 0) &gt; NVL(ril.MAX_STOCK, 0)                 THEN 'ABOVE MAX'             ELSE 'UNKNOWN'     END                                                 AS \"Stock Position\",      open_ord.OPEN_ORDER_COUNT                       AS \"Open Order Count\",     open_ord.OPEN_ORDER_QTY                         AS \"Open Order QTY\",     CASE WHEN NVL(ils.STOCK_ON_HAND, 0) = 0 AND last_ord.LAST_ORDER_DATE IS NULL THEN 'CRITICAL - OOS and Never Ordered'             WHEN NVL(ils.STOCK_ON_HAND, 0) = 0 AND TRUNC(SYSDATE) - TRUNC(last_ord.LAST_ORDER_DATE) &gt; 30                 THEN 'CRITICAL - OOS, No Order in 30+ Days'             WHEN NVL(ils.STOCK_ON_HAND, 0) &lt; NVL(ril.MIN_STOCK, 0)                 THEN 'HIGH - Below Min, No Order in 30+ Days'             WHEN last_ord.LAST_ORDER_DATE IS NULL                 THEN 'HIGH - Never Ordered, Repl Active'             WHEN TRUNC(SYSDATE) - TRUNC(last_ord.LAST_ORDER_DATE) &gt; 90                 THEN 'MEDIUM - No Order in 90+ Days'             ELSE 'LOW - Monitor'     END                                                 AS \"Urgency Flag\",      CASE WHEN ril.REPL_ORDER_CTRL = 'M' THEN 'Manual order control - buyer action required to raise PO'             WHEN ril.REPL_ORDER_CTRL = 'B'                 THEN 'Buyer worksheet - buyer must approve generated worksheet'             WHEN ril.REPL_ORDER_CTRL = 'A' AND last_ord.LAST_ORDER_DATE IS NULL                 THEN 'Auto order - check rplbld.pc batch and supplier setup'             WHEN sp.SUP_STATUS != 'A'                 THEN 'Supplier inactive - reactivate or assign alternate supplier'             WHEN NVL(isc.PICKUP_LEAD_TIME, 0) = 0 AND ril.STOCK_CAT IN ('C','D','L','W')                 THEN 'Pickup lead time missing - correct to allow repl order generation'             ELSE 'Review replenishment setup and last batch run log'     END                                                 AS \"Recommended Action\",      ril.LAST_UPDATE_DATETIME                        AS \"Last Repl Update\"  FROM     MFCS_RDS.RDS_WV_REPL_ITEM_LOC              ril      JOIN  MFCS_RDS.RDS_WV_ITEM_LOC             il    ON  ril.ITEM          = il.ITEM                                                      AND  ril.LOCATION      = il.LOC                                                      AND  ril.LOC_TYPE      = il.LOC_TYPE     JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER          im    ON  ril.ITEM          = im.ITEM                                                      AND  im.TRAN_LEVEL     = im.ITEM_LEVEL     JOIN  MFCS_RDS.RDS_WV_DEPS                 d     ON  im.DEPT           = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS                c     ON  im.DEPT           = c.DEPT                                                      AND  im.CLASS          = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS             sc    ON  im.DEPT           = sc.DEPT                                                      AND  im.CLASS          = sc.CLASS                                                      AND  im.SUBCLASS       = sc.SUBCLASS      LEFT JOIN MFCS_RDS.RDS_WV_STORE            st    ON  ril.LOCATION      = st.STORE                                                      AND  il.LOC_TYPE       = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH              wh     ON  ril.LOCATION      = wh.WH                                                      AND  il.LOC_TYPE       = 'W'      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH    ils    ON  ril.ITEM          = ils.ITEM                                                      AND  ril.LOCATION      = ils.LOC                                                      AND  ils.LOC_TYPE      = ril.LOC_TYPE      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY isc  ON  ril.ITEM          = isc.ITEM                                                      AND  ril.PRIMARY_REPL_SUPPLIER = isc.SUPPLIER                           