SELECT             ol.ITEM,             ol.LOCATION,             ol.LOC_TYPE,             MAX(oh.WRITTEN_DATE)                          AS last_order_date,             MAX(oh.ORDER_NO)                 KEEP (DENSE_RANK LAST ORDER BY oh.WRITTEN_DATE)                                                           AS last_order_no,             MAX(oh.STATUS)                 KEEP (DENSE_RANK LAST ORDER BY oh.WRITTEN_DATE)                                                           AS last_order_status,             MAX(oh.NOT_AFTER_DATE)                 KEEP (DENSE_RANK LAST ORDER BY oh.WRITTEN_DATE)                                                           AS last_not_after_date         FROM  MFCS_RDS.RDS_WV_ORDLOC              ol         JOIN  MFCS_RDS.RDS_WV_ORDHEAD             oh   ON  ol.ORDER_NO    = oh.ORDER_NO         WHERE oh.STATUS IN ('W','S','A','C')         GROUP BY ol.ITEM, ol.LOCATION, ol.LOC_TYPE     ) last_ord                                            ON  ril.ITEM      = last_ord.ITEM                                                          AND  ril.LOCATION  = last_ord.LOCATION                                                          AND  ril.LOC_TYPE  = last_ord.LOC_TYPE      LEFT JOIN (

