SELECT\\n            ol.ITEM,\\n            ol.LOCATION,\\n            ol.LOC_TYPE,\\n            MAX(oh.WRITTEN_DATE)                          AS last_order_date,\\n            MAX(oh.ORDER_NO)\\n                KEEP (DENSE_RANK LAST ORDER BY oh.WRITTEN_DATE)\\n                                                          AS last_order_no,\\n            MAX(oh.STATUS)\\n                KEEP (DENSE_RANK LAST ORDER BY oh.WRITTEN_DATE)\\n                                                          AS last_order_status,\\n            MAX(oh.NOT_AFTER_DATE)\\n                KEEP (DENSE_RANK LAST ORDER BY oh.WRITTEN_DATE)\\n                                                          AS last_not_after_date\\n        FROM  MFCS_RDS.RDS_WV_ORDLOC              ol\\n        JOIN  MFCS_RDS.RDS_WV_ORDHEAD             oh   ON  ol.ORDER_NO    = oh.ORDER_NO\\n        WHERE oh.STATUS IN ('W','S','A','C')\\n        GROUP BY ol.ITEM, ol.LOCATION, ol.LOC_TYPE\\n    ) last_ord                                            ON  ril.ITEM      = last_ord.ITEM\\n                                                         AND  ril.LOCATION  = last_ord.LOCATION\\n                                                         AND  ril.LOC_TYPE  = last_ord.LOC_TYPE\\n\\n    LEFT JOIN (\\n

-- ── Query 5 ────────────────────────────────────────────────────────────
SELECT\\n            ol.ITEM,\\n            ol.LOCATION,\\n            COUNT(DISTINCT oh.ORDER_NO)                   AS open_order_count,\\n            SUM(ol.QTY_ORDERED - NVL(ol.QTY_RECEIVED, 0)) AS open_order_qty\\n        FROM  MFCS_RDS.RDS_WV_ORDLOC              ol\\n        JOIN  MFCS_RDS.RDS_WV_ORDHEAD             oh   ON  ol.ORDER_NO    = oh.ORDER_NO\\n        WHERE oh.STATUS IN ('W','S','A')\\n        GROUP BY ol.ITEM, ol.LOCATION\\n    ) open_ord                                            ON  ril.ITEM      = open_ord.ITEM\\n                                                         AND  ril.LOCATION  = open_ord.LOCATION\\n\\nWHERE\\n    ril.REPL_METHOD     IS NOT NULL\\n    AND il.STATUS       IN ('A','C')\\n    AND im.STATUS        = 'A'\\n    AND (\\n        last_ord.LAST_ORDER_DATE IS NULL\\n        OR TRUNC(last_ord.LAST_ORDER_DATE) &lt; TRUNC(SYSDATE) - 30\\n    )\\n\\nORDER BY\\n    CASE\\n        WHEN NVL(ils.STOCK_ON_HAND,0) = 0 AND last_ord.LAST_ORDER_DATE IS NULL\\n        THEN 'CRITICAL - OOS and Never Ordered'\\n        WHEN NVL(ils.STOCK_ON_HAND,0) = 0\\n             AND TRUNC(SYSDATE) - TRUNC(last_ord.LAST_ORDER_DATE) &gt; 30\\n        THEN 'CRITICAL - OOS, No Order in 30+ Days'\\n        WHEN NVL(ils.STOCK_ON_HAND,0) &lt; NVL(ril.MIN_STOCK,0)\\n        THEN 'HIGH - Below Min, No Order in 30+ Days'\\n        WHEN last_ord.LAST_ORDER_DATE IS NULL\\n        THEN 'HIGH - Never Ordered, Repl Active'\\n        WHEN TRUNC(SYSDATE) - TRUNC(last_ord.LAST_ORDER_DATE) &gt; 90\\n        THEN 'MEDIUM - No Order in 90+ Days'\\n        ELSE 'LOW - Monitor'\\n    END,\\n    (TRUNC(SYSDATE) - TRUNC(last_ord.LAST_ORDER_DATE)) DESC NULLS FIRST,\\n    d.DEPT_NAME,\\n    im.ITEM_DESC,\\n    CASE il.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END;\"},\"editorCurrentState\":false,\"joins\":{\"tables\":[]}}</ds:uiOptions><ds:version>v5</ds:version></ds:datasetImportOptions>","business-model":"\"\"","active":true,"custom-attrs":"{\"src_parquet_verified\":\"true\"}","description":"External dataset","display-name":"Manual Query","locale":"sys","is-user-striped":false,"file-length":0,"type":"sql","properties-last-modified":"2026-07-14T06:30:48.060+0000","connection-namespace":"disadmin_disadmin_APPID","private-connection":false,"credential-exists":true,"connection-name":"Remote RDS MFCS Connection","provider-type":"db","provider-name":"oracle","sso-enabled":false,"datamodelname":"'ReCommon'.'RPT_406_Items_Rep_Never_Ordered'","parent-namespace":"ReCommon","parent-name":"RPT_406_Items_Rep_Never_Ordered","data-access-mode":"auto","is-data-cacheable":true,"checkpoint-metadata-stale":false,"owner-guid":"ReCommon","is-temporary":false},"datasetType":"EMBEDDED","datamodelTwoPartName":"'ReCommon'.'RPT_406_Items_Rep_Never_Ordered'"}
